async function recolorEmojiSvg(dataUrl,from,to){const xml=new DOMParser().parseFromString(await(await fetch(dataUrl)).text(),'image/svg+xml');if(xml.querySelector('parsererror'))throw new Error('SVG non leggibile');const norm=v=>(v||'').toLowerCase().replace(/\s/g,''),colors=new Set(['black','#000','#000000','rgb(0,0,0)',norm(from)]);for(const el of [xml.documentElement,...xml.querySelectorAll('*')]){for(const attr of ['stroke','fill'])if(colors.has(norm(el.getAttribute(attr))))el.setAttribute(attr,to);if(el.hasAttribute('style')){el.setAttribute('style',el.getAttribute('style').replace(/(stroke|fill)\s*:\s*([^;]+)/gi,(all,prop,value)=>colors.has(norm(value))?prop+':'+to:all))}}return dataUrlFromBlob(new Blob([new XMLSerializer().serializeToString(xml)],{type:'image/svg+xml'}))}
async function applyEmojiInk(){const selected=selectionObjects().filter(o=>o.objectType==='emoji'),ink=$('emojiInk').value;state.emojiInk=ink;if(!selected.length){toast('Colore impostato per le prossime OpenMoji outlined');return}const page=currentPage;canvas.discardActiveObject();let count=0;for(const obj of selected){const asset=state.assets[obj.assetId];if(asset?.meta?.style!=='black')continue;const dataUrl=await recolorEmojiSvg(asset.dataUrl,asset.meta.ink||'#000000',ink),id=uid('asset');state.assets[id]={...asset,id,dataUrl,meta:{...asset.meta,ink},sourceKey:'openmoji:black:'+asset.meta.hex+':'+ink};if(currentPage!==page)break;const im=new Image();im.src=dataUrl;await im.decode();obj.setElement(im,{width:obj.width,height:obj.height});obj.assetId=id;obj.setCoords();count++}if(currentPage===page){canvas.requestRenderAll();saveActivePage()}toast(count?'Colore aggiornato su '+count+' emoji':'Seleziona OpenMoji outlined, non la variante a colori')}

