const FONT_CATEGORIES=[['all','Tutti'],['child','Cicciottelli'],['round','Rotondi'],['square','Squadrati'],['art','Artistici'],['serif','Serif'],['sans','Sans serif'],['hand','Scrittura'],['mono','Monospazio'],['outline','Outline nativi']];
function matchesFontCategory(f,category){switch(category){case 'child':return f.weight>=72&&f.shape>=55;case 'round':return f.shape>=72;case 'square':return f.shape<=28;case 'art':return f.art>=70;case 'serif':return f.category==='serif';case 'sans':return f.category==='sans-serif';case 'hand':return f.category==='handwriting';case 'mono':return f.category==='monospace';case 'outline':return !!f.native;default:return true}}
function fontKeywords(f){const tags=[f.name,f.category];for(const [id,label] of FONT_CATEGORIES)if(id!=='all'&&matchesFontCategory(f,id))tags.push(label);if(matchesFontCategory(f,'child'))tags.push('cicciottello cicciottelli bambini bambino colorabile colorabili gonfio bubble kids');if(matchesFontCategory(f,'round'))tags.push('rotondo tondo rotondeggiante rotondeggianti morbido rounded');if(matchesFontCategory(f,'square'))tags.push('squadrato geometrico pixel square');if(matchesFontCategory(f,'art'))tags.push('artistico decorativo creativo artistic');if(matchesFontCategory(f,'hand'))tags.push('manoscritto mano calligrafico');return tags.join(' ').toLocaleLowerCase(appLocale())}
function renderFontCategories(){const panel=$('fontCategories');panel.replaceChildren();FONT_CATEGORIES.forEach(([id,label])=>{const b=document.createElement('button');b.className='font-category'+(state.fontCategory===id?' active':'');b.role='tab';b.setAttribute('aria-selected',String(state.fontCategory===id));b.textContent=label;b.title=state.fontCatalog.filter(f=>matchesFontCategory(f,id)).length+' famiglie';b.onclick=()=>{state.fontCategory=id;fontPageLimit=60;renderFontResults()};panel.append(b)})}
