async function ensurePuter(){if(window.puter?.ai?.txt2img)return;if(!puterReady)puterReady=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://js.puter.com/v2/';script.async=true;let done=false;const finish=e=>{if(done)return;done=true;clearTimeout(timer);if(e){puterReady=null;script.remove();reject(e)}else resolve()};const timer=setTimeout(()=>finish(new Error('Puter non raggiungibile. Controlla la connessione o il filtro del browser.')),15000);script.onload=()=>window.puter?.ai?finish():finish(new Error('SDK Puter non disponibile'));script.onerror=()=>finish(new Error('Caricamento Puter bloccato dal browser o dalla rete'));document.head.append(script)});return puterReady}
