async function setAiReference(file){if(!file)return;if(file.size>12*1024*1024){toast('Il riferimento deve essere inferiore a 12 MB');return}try{const raw=await fileToDataUrl(file),im=new Image();im.src=raw;await im.decode();const scale=Math.min(1,2048/Math.max(im.naturalWidth,im.naturalHeight)),c=document.createElement('canvas');c.width=Math.round(im.naturalWidth*scale);c.height=Math.round(im.naturalHeight*scale);c.getContext('2d').drawImage(im,0,0,c.width,c.height);state.aiReference={dataUrl:c.toDataURL('image/png'),mime:'image/png',name:file.name||'Riferimento dal canvas',width:c.width,height:c.height};syncReferenceUI()}catch(e){toast('Immagine di riferimento non leggibile')}}
