 window.addEventListener('keydown',e=>{const editable=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)||document.activeElement?.isContentEditable;if(e.key==='F1'){e.preventDefault();openHelp();return}if(!$('helpLayer').classList.contains('hidden')){if(e.key==='Escape'){e.preventDefault();closeHelp()}if(e.key==='Tab'){const nodes=[...$('helpLayer').querySelectorAll('button,a[href],input')],first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}return}if(editable)return;const key=e.key.toLowerCase(),ctrl=e.ctrlKey||e.metaKey;let handled=true;if(ctrl&&key==='d')duplicateSelection();else if(ctrl&&key==='s')exportJson();else if(ctrl&&key==='a'&&!cropSession){const objects=canvas.getObjects().filter(o=>!o.excludeProject);if(objects.length)canvas.setActiveObject(new fabric.ActiveSelection(objects,{canvas}));canvas.requestRenderAll()}else if(key==='f'&&!ctrl)setZoom('fit');else if(key==='v'&&!ctrl){setPan(false);state.selectionMode=true;canvas.selection=true;$('selectTool').classList.add('active')}else if(key==='h'&&!ctrl)setPan(!panMode);else if(key==='g'&&!ctrl)$('gridTool').click();else if(key==='r'&&!ctrl)$('rotateTool').click();else if(e.key==='Escape'){if(!$('objectMenu').classList.contains('hidden'))hideContext();else handled=false}else if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)&&canvas.getActiveObject()&&!canvas.getActiveObject().chicLocked&&!cropSession){const a=canvas.getActiveObject(),step=e.shiftKey?10:1;a.set({left:a.left+(e.key==='ArrowLeft'?-step:e.key==='ArrowRight'?step:0),top:a.top+(e.key==='ArrowUp'?-step:e.key==='ArrowDown'?step:0)});a.setCoords();canvas.requestRenderAll();saveActivePage()}else handled=false;if(handled){e.preventDefault();e.stopImmediatePropagation()}},true);
