// Workspace persistence, undo/redo and the complete emoji browser.
const MEMORY_KEY='chicCanva.autosave.v6', AUTOSAVE_DIRTY_KEY='chicCanva.autosave.pending.v7', AUTOSAVE_CURRENT='workspace-current', AUTOSAVE_PREVIOUS='workspace-previous', PREF_KEY='chicCanva.preferences.v6', BG_CACHE='chicCanva.models.imgly-1.7.0-ort-1.21.0';
let preferences={limit:30,history:false,autosave:true,model:'isnet_quint8',device:'auto',cloudBackup:false,cloudSync:false,cloudHideSyncBadge:false},historyEntries=[],historyCursor=-1,historyReady=false,historyRestoring=false,snapshotting=false,actionDepth=0,commitTimer=0,autosaveTimer=0,storageQueue=Promise.resolve(),memoryEpoch=0,bgCacheEpoch=0,bgWorking=false,emojiLimit=120,emojiFilterKey='',urlTarget='image',lastSavedPayload='',canvasGestureActive=false;
const cloneData=x=>JSON.parse(JSON.stringify(x));
const basePayload=projectPayload,baseSave=saveActivePage,baseSync=syncUiFromState;
const baseSelectionChanged=selectionChanged;selectionChanged=function(){if(!snapshotting)baseSelectionChanged()};
function capturePayload(){snapshotting=true;try{return basePayload()}finally{snapshotting=false}}
function readPreferences(){try{const p=JSON.parse(localStorage.getItem(PREF_KEY)||'null');if(p){preferences.limit=clamp(Number(p.limit)||30,1,100);preferences.history=!!p.history;preferences.autosave=p.autosave!==false;preferences.model=['isnet_quint8','isnet_fp16','isnet'].includes(p.model)?p.model:'isnet_quint8';preferences.device=['auto','cpu','gpu'].includes(p.device)?p.device:'auto';preferences.cloudBackup=!!p.cloudBackup;preferences.cloudSync=!!p.cloudSync;preferences.cloudHideSyncBadge=!!p.cloudHideSyncBadge}}catch(e){console.warn('Preferenze non disponibili',e)}}
function writePreferences(){try{localStorage.setItem(PREF_KEY,JSON.stringify(preferences))}catch(e){memoryMessage('Preferenze non salvate: memoria del browser non disponibile.')}}
function memoryMessage(s){$('memoryStatus').textContent=s;$('settingsBtn').title=s}
function compactHistoryEntry(payload){const source=payload?.state||{},entry={state:{mode:source.mode||'custom',pageIndex:cloneData(source.pageIndex||{whole:0,single:0,custom:0}),workspaceCustom:source.workspaceCustom!==false,customCounter:Number(source.customCounter)||1},pages:cloneData(payload?.pages||{whole:[],single:[],custom:[]})};if(payload?.historyInfo)entry.historyInfo=cloneData(payload.historyInfo);return entry}
function historySnapshot(){return compactHistoryEntry(capturePayload())}
// Undo/redo follows the printable project: pages, page properties and their objects.
// Tool choices, draft text, prompts, references and UI preferences remain persistent
// project settings, but cannot create an undo step or change while travelling history.
function historySignature(payload){return JSON.stringify({pages:payload?.pages||{}})}
function syncHistoryButtons(){$('undoBtn').disabled=!historyReady||historyRestoring||actionDepth>0||historyCursor<=0;$('redoBtn').disabled=!historyReady||historyRestoring||actionDepth>0||historyCursor>=historyEntries.length-1;$('mobileUndo').disabled=$('undoBtn').disabled;$('mobileRedo').disabled=$('redoBtn').disabled;$('historyStatus').textContent=Math.max(0,historyCursor)+' / '+Math.max(0,historyEntries.length-1)}
function trimHistory(){const excess=historyEntries.length-(preferences.limit+1);if(excess>0){const front=Math.min(excess,historyCursor);historyEntries.splice(0,front);historyCursor-=front;if(historyEntries.length>preferences.limit+1)historyEntries.splice(preferences.limit+1)}syncHistoryButtons()}
function canvasTransformActive(){return canvasGestureActive||!!(canvas&&canvas._currentTransform)}
function commitHistory(){clearTimeout(commitTimer);if(canvasTransformActive()){commitTimer=setTimeout(commitHistory,250);return}if(!historyReady||historyRestoring||actionDepth||loadingPage||cropSession)return;const entry=historySnapshot(),current=historyEntries[historyCursor];if(!current||historySignature(entry)!==historySignature(current)){historyEntries.splice(historyCursor+1);historyEntries.push(entry);historyCursor=historyEntries.length-1;trimHistory();scheduleAutosave()}syncHistoryButtons()}
function scheduleCommit(){if(!historyReady||historyRestoring)return;clearTimeout(commitTimer);commitTimer=setTimeout(commitHistory,350)}
