function dbOperation(mode,operation){return new Promise((resolve,reject)=>{const request=indexedDB.open('chicCanva-storage',1);request.onupgradeneeded=()=>request.result.createObjectStore('projects');request.onerror=()=>reject(request.error);request.onsuccess=()=>{const db=request.result,tx=db.transaction('projects',mode);let result;try{result=operation(tx.objectStore('projects'))}catch(e){db.close();reject(e);return}tx.oncomplete=()=>{db.close();resolve(result?.result)};tx.onerror=()=>{db.close();reject(tx.error)};tx.onabort=()=>{db.close();reject(tx.error||new Error('Salvataggio interrotto'))}}})}
