// Only IMG.LY model/runtime downloads use this cache; never caches user images.
globalThis.__chicBgFetch=async function(input,options={}){const url=new URL(String(input));if(url.origin!=='https://staticimgly.com')return fetch(input,options);const epoch=bgCacheEpoch;let cache=null;try{if('caches' in window){cache=await caches.open(BG_CACHE);const hit=await cache.match(url.href);if(hit){$('bgCacheStatus').textContent='Modello e runtime: lettura dalla cache del browser.';return hit}}}catch(e){console.warn('Cache modelli non disponibile',e)}const response=await fetch(input,{...options,cache:'no-store'});if(response.ok&&cache&&epoch===bgCacheEpoch){try{await cache.put(url.href,response.clone());$('bgCacheStatus').textContent='Risorse salvate nella cache per i prossimi avvii.'}catch(e){$('bgCacheStatus').textContent='Cache piena o non disponibile: il download funzionerà senza salvataggio.'}}return response};

const EMOJI_GROUPS={'smileys-emotion':'Faccine ed emozioni','people-body':'Persone e corpo','component':'Componenti e varianti','animals-nature':'Animali e natura','food-drink':'Cibo e bevande','travel-places':'Viaggi e luoghi','activities':'Attività','objects':'Oggetti','symbols':'Simboli','flags':'Bandiere','extras-openmoji':'Extra OpenMoji','extras-unicode':'Extra Unicode'};
let emojiTranslatedQuery='',emojiTranslationNote='',emojiTranslationSerial=0,emojiSearchBusy=false;
function emojiActiveQuery(){return ($('emojiTranslate').checked?emojiTranslatedQuery:$('emojiSearch').value.trim()).toLocaleLowerCase()}
function emojiMatches(){const q=emojiActiveQuery(),category=$('emojiCategory').value;let all=emojiData.filter(e=>!q||`${e.annotation||''} ${e.tags||''} ${e.openmoji_tags||''} ${e.emoji||''} ${e.hexcode||''} ${EMOJI_GROUPS[e.group]||e.group} ${e.subgroups||''}`.toLocaleLowerCase().includes(q));if(q)return all;if(category!=='all'&&category!=='relevant')return all.filter(e=>e.group===category);if(category==='relevant'){const popular=new Set(graphemes('😀😊😍🥰😂😎🤔👏👍👋❤️⭐🌈☀️🌻🐶🐱🦋🍎🎈🎨📚✏️🏫⚽'));const score=e=>(popular.has(e.emoji)?200:0)+(!String(e.group).startsWith('extras')?50:0)+(/book|pencil|school|teacher/.test(e.annotation||'')?40:0)-(e.hexcode?.includes('-')?10:0);all=[...all].sort((a,b)=>score(b)-score(a)||(a.order||0)-(b.order||0))}return all}
renderEmojiGrid=function(){if(!$('emojiCategory'))return;const select=$('emojiCategory'),old=select.value||'relevant',groups=[...new Set(emojiData.map(e=>e.group).filter(Boolean))],options=[['relevant','Più rilevanti'],['all','Tutte le emoji'],...groups.map(g=>[g,EMOJI_GROUPS[g]||g.replaceAll('-',' ')])];if(select.options.length!==options.length||options.some(([value],index)=>select.options[index]?.value!==value)){select.replaceChildren();for(const [value,label] of options){const option=new Option('',value);setLocalizedText(option,label);select.add(option)}select.value=[...select.options].some(o=>o.value===old)?old:'relevant'}else options.forEach(([value,label])=>setLocalizedText([...select.options].find(option=>option.value===value),label));const key=select.value+'|'+$('emojiSearch').value+'|'+emojiTranslatedQuery;if(key!==emojiFilterKey){emojiLimit=120;emojiFilterKey=key;$('emojiGrid').scrollTop=0}const all=emojiMatches(),list=all.slice(0,emojiLimit),note=emojiTranslationNote?' · '+emojiTranslationNote:'';setLocalizedText($('emojiCount'),`${list.length} di ${all.length} emoji`+($('emojiSearch').value.trim()?' · ricerca globale':'')+note);$('emojiGrid').replaceChildren();for(const e of list){const b=document.createElement('button');b.className='emoji-btn';b.title=e.annotation||e.emoji;b.setAttribute('aria-label',b.title);const image=document.createElement('img');image.loading='lazy';image.src=openMojiUrl(e.hexcode,state.emojiStyle);image.alt='';b.append(image);b.onclick=()=>addOpenMoji(e);$('emojiGrid').append(b)}if(list.length<all.length){const more=document.createElement('button');more.className='btn emoji-more';setLocalizedText(more,'Mostra altre 120');more.onclick=()=>{const top=$('emojiGrid').scrollTop;emojiLimit+=120;renderEmojiGrid();$('emojiGrid').scrollTop=top};$('emojiGrid').append(more)}if(!all.length)setLocalizedText($('emojiCount'),(emojiData.length?'Nessuna emoji trovata.':'Caricamento catalogo OpenMoji…')+note)};
function syncEmojiSearchMode(){const translated=$('emojiTranslate').checked,button=$('emojiSearchBtn');button.classList.toggle('hidden',!translated);button.disabled=emojiSearchBusy;if(!translated){emojiTranslatedQuery='';emojiTranslationNote='';renderEmojiGrid()}else $('emojiCount').textContent=$('emojiSearch').value.trim()?'Premi Invio o la lente per tradurre e cercare.':'Scrivi una parola, poi premi Invio o la lente.'}
function setEmojiSearchBusy(busy,message='Traduzione e ricerca…'){emojiSearchBusy=busy;const button=$('emojiSearchBtn');button.disabled=busy;button.setAttribute('aria-busy',String(busy));button.innerHTML=busy?'<span class="spinner" aria-hidden="true"></span>':'<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5" fill="none" stroke="currentColor" stroke-width="2"/><path d="m15.5 15.5 5 5" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg>';$('emojiGrid').toggleAttribute('aria-busy',busy);if(busy){$('emojiCount').innerHTML='<span class="spinner" aria-hidden="true"></span> '+message;$('emojiGrid').innerHTML='<div class="emoji-search-loading"><span class="spinner" aria-hidden="true"></span><span>'+message+'</span></div>'}}
async function updateEmojiSearch(){const serial=++emojiTranslationSerial,keyword=$('emojiSearch').value.trim();emojiTranslatedQuery='';emojiTranslationNote='';if(!$('emojiTranslate').checked||!keyword){renderEmojiGrid();return}setEmojiSearchBusy(true);try{await new Promise(resolve=>setTimeout(resolve,0));const result=await translateEmojiKeyword(keyword);if(serial!==emojiTranslationSerial)return;emojiTranslatedQuery=result.translated;emojiTranslationNote=result.note;renderEmojiGrid();await new Promise(resolve=>setTimeout(resolve,0))}finally{if(serial===emojiTranslationSerial)setEmojiSearchBusy(false)}}
async function styleEmojiSvg(original,from,ink,factor){const recolored=await recolorEmojiSvg(original,from,ink),xml=new DOMParser().parseFromString(await(await fetch(recolored)).text(),'image/svg+xml'),root=xml.documentElement;for(const e of [root,...root.querySelectorAll('*')]){if(e.hasAttribute('stroke-width')){const n=parseFloat(e.getAttribute('stroke-width'));if(Number.isFinite(n))e.setAttribute('stroke-width',String(n*factor))}if(e.hasAttribute('style'))e.setAttribute('style',e.getAttribute('style').replace(/stroke-width\s*:\s*([\d.]+)/gi,(_,n)=>'stroke-width:'+(Number(n)*factor)))}return dataUrlFromBlob(new Blob([new XMLSerializer().serializeToString(xml)],{type:'image/svg+xml'}))}
const baseAssetFromUrl=assetFromUrl;
assetFromUrl=async function(url,meta={}){const id=await baseAssetFromUrl(url,meta),a=state.assets[id];if(a.kind==='emoji'&&a.meta?.style==='black'){a.originalDataUrl=a.dataUrl;a.meta.originalInk=a.meta.ink;a.meta.strokeFactor=state.emojiStroke||1;a.dataUrl=await styleEmojiSvg(a.originalDataUrl,a.meta.originalInk,a.meta.ink,a.meta.strokeFactor)}return id};
