applyEmojiInk=async function(){const selected=selectionObjects().filter(o=>o.objectType==='emoji');state.emojiInk=$('emojiInk').value;state.emojiStroke=clamp(Number($('emojiStroke').value)||1,.5,3);const page=currentPage;canvas.discardActiveObject();let count=0;for(const o of selected){const a=state.assets[o.assetId];if(a?.meta?.style!=='black')continue;const original=a.originalDataUrl||a.dataUrl,dataUrl=await styleEmojiSvg(original,a.meta.originalInk||a.meta.ink||'#000000',state.emojiInk,state.emojiStroke),id=uid('asset');state.assets[id]={...a,id,dataUrl,originalDataUrl:original,sourceKey:undefined,meta:{...a.meta,ink:state.emojiInk,strokeFactor:state.emojiStroke}};const im=new Image();im.src=dataUrl;await im.decode();if(currentPage!==page)break;o.setElement(im,{width:o.width,height:o.height});o.assetId=id;o.setCoords();count++}canvas.requestRenderAll();saveActivePage();toast(count?'Contorno aggiornato su '+count+' emoji':'Stile impostato per le prossime emoji outlined')};
function openImageUrl(target){urlTarget=target;$('urlTitle').textContent=target==='reference'?'Riferimento AI da URL':'Carica immagine da URL';$('imageUrlInput').value='';$('imageUrlStatus').textContent='';$('urlDialog').showModal();$('imageUrlInput').focus()}
async function fetchImageFile(address){let url;try{url=new URL(address)}catch(e){throw new Error('Inserisci un indirizzo completo https://…')}if(!['http:','https:'].includes(url.protocol)||url.username||url.password)throw new Error('Usa un URL HTTP o HTTPS senza credenziali');const response=await fetch(url.href,{signal:AbortSignal.timeout(20000),credentials:'omit'});if(!response.ok)throw new Error('Il sito risponde HTTP '+response.status);const blob=await response.blob();if(blob.size>12*1024*1024)throw new Error('Immagine troppo grande: massimo 12 MB');const type=blob.type.split(';')[0];if(!type.startsWith('image/'))throw new Error('Il link non restituisce un’immagine');const im=new Image(),temporary=URL.createObjectURL(blob);try{im.src=temporary;await im.decode();if(!im.naturalWidth||!im.naturalHeight)throw new Error('Immagine non leggibile')}finally{URL.revokeObjectURL(temporary)}return new File([blob],decodeURIComponent(url.pathname.split('/').at(-1)||'Immagine da URL'),{type})}
async function confirmImageUrl(){const btn=$('confirmImageUrl');btn.disabled=true;$('imageUrlStatus').textContent='Caricamento…';try{const file=await fetchImageFile($('imageUrlInput').value.trim());if(urlTarget==='reference')await setAiReference(file);else await handleImageUpload(file);$('urlDialog').close();scheduleCommit()}catch(e){$('imageUrlStatus').textContent=e instanceof TypeError?'Il sito non consente il caricamento (CORS), è bloccato o non raggiungibile. Puoi caricare il file dal computer.':e.message}finally{btn.disabled=false}}

