let projects=[],activeProjectId=null,workspaceReady=false,projectSwitching=false,projectSerial=1,projectClipboard=null,pasteSerial=0,projectDialogAction=null,projectDialogId=null,fontPreviewTimer=0;
const DOCUMENT_FIELDS=['splitText','fitAxis','fitMarginMm','specialText','specialUppercase','specialEmoji','specialExplicit','specialPrev','specialNext','specialApostrophe','specialOrientation','specialFit','specialDestination','specialOperation','bgAutoColor','bgEverywhere','bgColor','bgTolerance','aiProvider','aiModel','aiQuality','aiRatio','aiStyle','aiPrompt','aiReferenceScale','aiChromaKey','aiRemoveBackground'];
const v6Capture=capturePayload,v6FullPayload=fullPayload,v6Restore=restoreSnapshot,v6Adopt=adoptProject,v6Commit=commitHistory,v6Sync=syncUiFromState;
function documentFields(){return Object.fromEntries(DOCUMENT_FIELDS.map(id=>[id,$(id).type==='checkbox'?$(id).checked:$(id).value]))}
function restoreDocumentFields(ui={}){for(const id of DOCUMENT_FIELDS)if(id in ui){if($(id).type==='checkbox')$(id).checked=!!ui[id];else $(id).value=ui[id]}updateTextModeUI();$('specialCurrentOptions').classList.toggle('hidden',$('specialDestination').value!=='current')}
capturePayload=function(){const p=v6Capture();p.state.workspaceCustom=true;p.state.documentFields=documentFields();return p};
function activeProject(){return projects.find(p=>p.id===activeProjectId)}
function contentSignature(payload){return historySignature(payload)}
function currentDocument(includeHistory=true){const p=v6FullPayload(includeHistory);p.version=7;p.name=activeProject()?.name||localizedProjectName(1);p.state.workspaceCustom=true;p.state.documentFields=documentFields();return cloneData(p)}
function storeActiveDocument(){if(!workspaceReady||projectSwitching||historyRestoring||loadingPage)return;const record=activeProject();if(record)record.payload=currentDocument(true)}
fullPayload=function(includeHistory=preferences.history){const p=v6FullPayload(includeHistory);p.version=7;p.name=activeProject()?.name||localizedProjectName(1);if(workspaceReady){const current=activeProject();if(current&&!projectSwitching&&!historyRestoring){current.payload=cloneData({...p,history:{version:1,limit:preferences.limit,cursor:historyCursor,entries:cloneData(historyEntries)}})}p.workspace={version:1,activeId:activeProjectId,serial:projectSerial,projects:cloneData(projects)}}return p};
projectPayload=function(){return currentDocument(preferences.history)};
const v6Decode=decodeMemory;decodeMemory=function(text){const p=v6Decode(text);for(const record of p.workspace?.projects||[])for(const a of Object.values(record.payload?.assets||{}))a.originalDataUrl??=a.dataUrl;return p};
function normalizeCustomSnapshot(snap){const result=cloneData(snap);if(!result.state.workspaceCustom)throw new Error('Usa un progetto chicCanva v7');result.state.mode='custom';result.pages.whole=[];result.pages.single=[];return result}
function normalizeCustomProject(input){validateProject(input);if(input.version!==7)throw new Error('Formato richiesto: chicCanva v7');const p=normalizeCustomSnapshot(input);p.version=7;delete p.workspace;if(p.history){p.history.entries=p.history.entries.map(normalizeCustomSnapshot)}return p}
ensurePages=function(){state.mode='custom';state.pages.whole=[];state.pages.single=[];if(!state.pages.custom.length)state.pages.custom=[makePage(localizedPageName(1),210,297)];state.pageIndex={whole:0,single:0,custom:clamp(state.pageIndex?.custom||0,0,state.pages.custom.length-1)}};
restoreSnapshot=async function(snap,assets=state.assets){const migrated=normalizeCustomSnapshot(snap);await v6Restore(migrated,assets);restoreDocumentFields(migrated.state.documentFields);refreshFontPreviews();};
adoptProject=async function(p,includeHistory){const migrated=normalizeCustomProject(p);await v6Adopt(migrated,includeHistory);restoreDocumentFields(migrated.state.documentFields)};
commitHistory=function(){v6Commit();if(workspaceReady)renderProjectTabs()};
function workspaceBusy(){return projectSwitching||actionDepth>0||loadingPage||historyRestoring||bgWorking}
function renderProjectTabs(){const box=$('projectTabs');if(!box)return;box.replaceChildren();for(const project of projects){const tab=document.createElement('div');tab.className='project-tab'+(project.id===activeProjectId?' active':'');const b=document.createElement('button');b.className='project-name';b.textContent=project.name;b.setAttribute('role','tab');b.setAttribute('aria-selected',String(project.id===activeProjectId));setLocalizedAttribute(b,'data-tip',project.name+' · doppio clic o clic destro per rinominare');setLocalizedAttribute(b,'aria-label',project.name+' · doppio clic o clic destro per rinominare');b.onclick=()=>activateProject(project.id).catch(e=>toast(e.message));const close=document.createElement('button');close.className='project-close';close.textContent='×';setLocalizedAttribute(close,'aria-label','Chiudi '+project.name);close.onclick=()=>requestCloseProject(project.id);tab.append(b,close);box.append(tab)}box.setAttribute('aria-busy',String(projectSwitching))}

function localizeWorkspaceQuickJump(){for(const button of $('sidebar')?.querySelectorAll('.quick-jump button')||[]){const source=button.dataset.jumpSource;if(!source)continue;setLocalizedText(button,source);setLocalizedAttribute(button,'data-tip','Apri '+source);setLocalizedAttribute(button,'aria-label','Apri '+source)}}
async function activateProject(id){if(id===activeProjectId)return;if(workspaceBusy()){toast('Attendi il completamento dell’operazione');return}if(cropSession){toast('Conferma o annulla il crop prima di cambiare progetto');return}commitHistory();storeActiveDocument();const target=projects.find(p=>p.id===id);if(!target)return;const previous=activeProjectId;projectSwitching=true;closePreview();hideContext();try{activeProjectId=id;await adoptProject(target.payload,true);renderProjectTabs()}catch(e){activeProjectId=previous;await adoptProject(activeProject().payload,true);throw e}finally{projectSwitching=false;renderProjectTabs();scheduleAutosave()}}
