function requestDeletePage(){if(state.pages.custom.length<=1){toast('Mantieni almeno una pagina');return}const page=state.pages.custom[state.pageIndex.custom];$('deletePageInfo').textContent='Vuoi eliminare «'+(page?.name||'questa pagina')+'»?';$('deletePageDialog').showModal();setTimeout(()=>$('deletePageCancel').focus(),0)}
function requestNewProject(){if(workspaceBusy()){toast('Attendi il completamento dell’operazione');return}projectDialogAction='new';$('projectDialogTitle').textContent='Crea un nuovo progetto';$('projectDialogInfo').textContent='Il progetto aperto resterà disponibile nella sua scheda.';$('projectNameRow').classList.remove('hidden');$('projectNameInput').value=localizedProjectName(projectSerial);$('projectConfirm').textContent='Crea progetto';$('projectExportClose').classList.add('hidden');$('projectDialog').showModal()}
