async function closeProject(id,exportFirst=false){if(workspaceBusy())return;storeActiveDocument();const p=projects.find(p=>p.id===id);if(!p)return;if(exportFirst)exportProjectRecord(p);const wasActive=id===activeProjectId;projects=projects.filter(p=>p.id!==id);if(!projects.length){const payload=blankProjectPayload(localizedProjectName(projectSerial++));projects=[{id:uid('project'),name:payload.name,payload,lastExport:null}]}if(wasActive){projectSwitching=true;activeProjectId=projects[0].id;try{await adoptProject(projects[0].payload,true)}finally{projectSwitching=false}}renderProjectTabs();memoryEpoch++;await storageQueue.catch(()=>{});if(preferences.autosave)await persistProject();toast('Progetto chiuso e rimosso dall’autosalvataggio')}
function projectExportArtifact(record){if(!record)throw new Error('Progetto non disponibile');if(record.id===activeProjectId)storeActiveDocument();const payload=cloneData(record.payload);if(!preferences.history)delete payload.history;delete payload.workspace;payload.name=record.name;const fileName=record.name.replace(/[<>:"/\\|?*]/g,'_')+'.json';return{fileName,blob:new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),payload}}
