function exportProjectRecord(record){const artifact=projectExportArtifact(record);download(artifact.fileName,artifact.blob);markProjectExported(record);return artifact.payload}
exportJson=function(){commitHistory();storeActiveDocument();const record=activeProject();if(record){exportProjectRecord(record);$('projectStatus').textContent='Progetto «'+record.name+'» esportato.'}};
importJsonFile=async function(file){try{if(workspaceBusy())throw new Error('Attendi il completamento dell’operazione');const p=JSON.parse(await file.text());if(p.workspace){const records=p.workspace.projects;if(!Array.isArray(records)||!records.length)throw new Error('Workspace vuoto');for(const r of records)normalizeCustomProject(r.payload);for(const r of records){const copy=cloneData(r.payload);if(!preferences.history)delete copy.history;await addProject(copy,r.name)}}else{const copy=cloneData(p);if(!preferences.history)delete copy.history;await addProject(copy,p.name||file.name.replace(/\.json$/i,''))}toast('Importato in una nuova scheda')}catch(e){console.error(e);toast('Importazione non riuscita: '+e.message)}};

// Compound letter/symbol objects retain their vectors and editable crop data.
const v6Serialize=serializeObject,v6Instantiate=instantiateObject;
serializeObject=function(o){if(o.objectType!=='group')return v6Serialize(o);return{id:o.projectId||uid('obj'),objectType:'group',left:o.left,top:o.top,scaleX:o.scaleX,scaleY:o.scaleY,angle:o.angle||0,originX:o.originX,originY:o.originY,flipX:!!o.flipX,flipY:!!o.flipY,opacity:o.opacity,width:o.width,height:o.height,children:o.getObjects().map(serializeObject).filter(Boolean)}};
instantiateObject=async function(d,target=canvas){if(d.objectType!=='group')return v6Instantiate(d,target);const temporary=new fabric.StaticCanvas(null),children=[];try{for(const child of d.children||[]){const o=await instantiateObject(child,temporary);if(o)children.push(o)}children.forEach(o=>temporary.remove(o));const group=new fabric.Group(children,{left:d.left,top:d.top,width:d.width,height:d.height,originX:d.originX||'center',originY:d.originY||'center',scaleX:d.scaleX??1,scaleY:d.scaleY??1,angle:d.angle||0,opacity:d.opacity??1,flipX:!!d.flipX,flipY:!!d.flipY},true);group.objectType='group';group.projectId=d.id||uid('obj');target.add(group);return group}finally{temporary.dispose()}};
function visitDescriptors(objects,fn){for(const o of objects||[]){fn(o);if(o.children)visitDescriptors(o.children,fn)}}
referencedAssets=function(snapshots){const ids=new Set();for(const snap of snapshots)for(const pages of Object.values(snap.pages))for(const p of pages)visitDescriptors(p.objects,o=>{if(o.assetId)ids.add(o.assetId)});return Object.fromEntries([...ids].filter(id=>state.assets[id]).map(id=>[id,state.assets[id]]))};
const v6Validate=validateProject;validateProject=function(p){v6Validate(p);for(const pages of Object.values(p.pages))for(const page of pages)visitDescriptors(page.objects,o=>{if(o.assetId&&!p.assets?.[o.assetId])throw new Error('Asset mancante nel gruppo')});return p};
async function tokenObject(token,target){const gs=graphemes(token);if(!(state.smartEmoji&&gs.some(isEmoji))){const o=makeTextObj(token,0,0,100);target.add(o);return o}const pieces=[];let x=0;for(const g of gs){let o;if(isEmoji(g))o=await instantiateObject(await makeGlyphDescriptor(g,0,0,100),target);else{o=makeTextObj(g,0,0,100);target.add(o)}if(!o)continue;o.set({left:x+o.getScaledWidth()/2,top:60});x+=o.getScaledWidth()+3;pieces.push(o)}if(pieces.length===1)return pieces[0];pieces.forEach(o=>target.remove(o));const group=new fabric.Group(pieces,{originX:'center',originY:'center'});group.objectType='group';group.projectId=uid('obj');target.add(group);return group}
textObjects=async function(text,split,target){const objects=[];let y=60;for(const line of text.split('\n')){const tokens=split?groupGraphemes(graphemes(line)).map(g=>g.join('')):[line];let x=0;for(const token of tokens){if(!token.trim())continue;const o=await tokenObject(token,target);o.set({left:x+o.getScaledWidth()/2,top:y});o.setCoords();x+=o.getScaledWidth()+8;objects.push(o)}y+=130}return objects};
// Preserve spaces while applying the same grouping rules to a row of separate objects.
async function splitTextObjects(text,target){const objects=[];let y=60;for(const line of text.split('\n')){let x=0;const raw=graphemes(line),groups=groupGraphemes(raw);let offset=0;for(const group of groups){while(offset<raw.length&&/^\s$/.test(raw[offset])){x+=28;offset++}const token=group.join(''),o=await tokenObject(token,target);o.set({left:x+o.getScaledWidth()/2,top:y});o.setCoords();x+=o.getScaledWidth()+8;objects.push(o);let left=group.length;while(offset<raw.length&&left){if(!/^\s$/.test(raw[offset]))left--;offset++}}y+=130}return objects}
addTextUnified=withHistory(async function(){if(loadingPage)return;syncStateFromUI();if(!state.text.trim())return;const b=$('buildTextBtn');b.disabled=true;try{saveActivePage();await loadFont(state.font);const text=state.uppercase?state.text.toLocaleUpperCase(appLocale()):state.text,objects=$('splitText').checked?await splitTextObjects(text,canvas):await textObjects(text,false,canvas);fitObjectList(objects,canvas.width,canvas.height);canvas.requestRenderAll();saveActivePage();toast('Testo aggiunto')}finally{b.disabled=false}});
updateTextModeUI=function(){state.mode='custom';$('splitTextRow').classList.remove('hidden');$('rebuildTextBtn').classList.add('hidden');$('singleOptions').classList.remove('hidden');$('orientationSeg').classList.add('hidden');$('orientationSeg').previousElementSibling.classList.add('hidden');$('customCardTitle').closest('.card').classList.remove('hidden');$('textModeHelp').textContent='Aggiunge una frase o singole lettere/gruppi alla pagina corrente.';$('previewBtn').disabled=false;for(const e of document.querySelectorAll('[data-symbol-options]'))e.classList.toggle('hidden',!$('splitText').checked)};
renderCustomChips=function(){const box=$('customPageChips');box.replaceChildren();state.pages.custom.forEach((p,i)=>{const b=document.createElement('button');b.className='page-chip'+(i===state.pageIndex.custom?' active':'');b.textContent=i+1;b.title=p.name;b.onclick=async()=>{if(workspaceBusy())return;saveActivePage();state.pageIndex.custom=i;await loadPage(p)};box.append(b)})};
previewSingleScale=function(){if(loadingPage)return;if(!scaleBaseline){saveActivePage();scaleBaseline=cloneData(state.pages.custom.map(p=>p.objects))}const f=clamp(Number($('singleScale').value)||100,10,500)/100;state.pages.custom.forEach((p,i)=>{p.objects=scaleBaseline[i].map(o=>({...o,left:p.widthMm*PX_PER_MM/2+(o.left-p.widthMm*PX_PER_MM/2)*f,top:p.heightMm*PX_PER_MM/2+(o.top-p.heightMm*PX_PER_MM/2)*f,scaleX:o.scaleX*f,scaleY:o.scaleY*f}))});const byId=new Map(currentPage.objects.map(o=>[o.id,o]));canvas.discardActiveObject();canvas.getObjects().forEach(o=>{const d=byId.get(o.projectId);if(d){o.set({left:d.left,top:d.top,scaleX:d.scaleX,scaleY:d.scaleY,dirty:true});o.setCoords()}});canvas.requestRenderAll();scheduleCommit()};

function copySelection(){if(cropSession||workspaceBusy()){toast('Completa l’operazione in corso');return}const selected=selectionObjects().filter(o=>!o.excludeProject);if(!selected.length){toast('Seleziona uno o più oggetti da copiare');return}canvas.discardActiveObject();const objects=selected.map(serializeObject);projectClipboard=cloneData({objects,assets:referencedAssets([{pages:{custom:[{objects}]}}])});pasteSerial=0;canvas.setActiveObject(selected.length===1?selected[0]:new fabric.ActiveSelection(selected,{canvas}));canvas.requestRenderAll();toast('Copiati '+selected.length+' oggetti · incolla anche in un’altra pagina o progetto')}
async function pasteSelection(){if(!projectClipboard){toast('Copia prima gli oggetti con Ctrl+C o dal menu');return}if(cropSession||loadingPage)return;pasteSerial++;const data=cloneData(projectClipboard),assetMap=new Map();for(const [old,a] of Object.entries(data.assets)){const id=uid('asset');assetMap.set(old,id);state.assets[id]={...a,id}}const remap=o=>{o.id=uid('obj');if(o.assetId)o.assetId=assetMap.get(o.assetId)||o.assetId};visitDescriptors(data.objects,remap);for(const asset of Object.values(data.assets)){const meta=asset?.meta?.colorizer;if(meta?.baseAssetId)meta.baseAssetId=assetMap.get(meta.baseAssetId)||meta.baseAssetId;if(meta?.sourceDescriptors)visitDescriptors(meta.sourceDescriptors,remap)}canvas.discardActiveObject();const copies=[];for(const d of data.objects){d.left+=20*pasteSerial;d.top+=20*pasteSerial;copies.push(await instantiateObject(d))}canvas.setActiveObject(copies.length===1?copies[0]:new fabric.ActiveSelection(copies,{canvas}));canvas.requestRenderAll();saveActivePage();toast('Oggetti incollati')}
pasteSelection=withHistory(pasteSelection);

function paintFontSample(id,font){const el=$(id);if(!el||!font)return;el.textContent='Outline';el.style.fontFamily=JSON.stringify(font)+',sans-serif';el.style.color=fontMeta(font).native||!state.outline?'#000000':'transparent';el.style.webkitTextStroke=!fontMeta(font).native&&state.outline?'1px #000000':'0'}
function refreshFontPreviews(){if(!$('currentFontSample'))return;$('currentFontName').textContent=state.font;paintFontSample('currentFontSample',state.font);const suggested=state.wizard.result?.name;if(suggested){paintFontSample('wizardFontSample',suggested);clearTimeout(fontPreviewTimer);fontPreviewTimer=setTimeout(()=>loadFont(suggested),180)}loadFont(state.font)}
