openPreview=function(){saveActivePage();const panel=$('previewPanel'),grid=$('previewGrid'),pages=[...state.pages.custom];panel.classList.remove('hidden');grid.replaceChildren();previewObserver?.disconnect();previewObserver=new IntersectionObserver(entries=>entries.forEach(async e=>{if(!e.isIntersecting)return;previewObserver.unobserve(e.target);const p=pages.find(p=>p.id===e.target.dataset.page);if(!p)return;try{const url=await renderPageDataUrl(p,Math.min(60,420/(p.widthMm*PX_PER_MM)*96));if(!e.target.isConnected)return;const img=document.createElement('img');img.src=url;img.alt=p.name;e.target.querySelector('.preview-sheet').append(img)}catch(e){e.target?.append?.('Anteprima non disponibile')}}),{root:panel,rootMargin:'400px'});pages.forEach((p,i)=>{const tile=document.createElement('button');tile.className='preview-page';tile.dataset.page=p.id;const sheet=document.createElement('div');sheet.className='preview-sheet';sheet.style.aspectRatio=p.widthMm+'/'+p.heightMm;const label=document.createElement('span');label.textContent=(i+1)+'. '+p.name+' · '+(p.widthMm>p.heightMm?'orizzontale':'verticale');tile.append(sheet,label);tile.onclick=async()=>{closePreview();saveActivePage();state.pageIndex.custom=i;await loadPage(p)};grid.append(tile);previewObserver.observe(tile)})};
