async function generateLetterPages(){
 if(workspaceBusy())return;const text=$('specialText').value;if(!text.trim()){toast('Inserisci il testo della funzione speciale');return}
 const explicit=$('specialExplicit').checked,destination=$('specialDestination').value,replace=$('specialOperation').value==='replace';
 if(destination==='current'&&replace&&!confirm('Rimpiazzare tutte le pagine del progetto aperto? Potrai annullare la modifica.'))return;
 const original={rules:cloneData(state.symbolRules),smart:state.smartEmoji,axis:$('fitAxis').value};syncStateFromUI();
 const options={rules:{prev:$('specialPrev').value,next:$('specialNext').value,smartApostrophe:$('specialApostrophe').checked},smart:$('specialEmoji').checked,axis:$('specialFit').value,text:$('specialUppercase').checked?text.toLocaleUpperCase(appLocale()):text};
 const [w,h]=$('specialOrientation').value==='landscape'?[297,210]:[210,297],button=$('runSpecial');button.disabled=true;actionDepth++;syncHistoryButtons();const pages=[];let error=null;
 try{
  state.symbolRules=options.rules;state.smartEmoji=options.smart;$('fitAxis').value=options.axis==='constant'?'contain':options.axis;await loadFont(state.font);
  const groups=explicit?options.text.split('^').map(x=>x.trim()).filter(Boolean):groupGraphemes(graphemes(options.text)).map(x=>x.join('')),prepared=[];
  for(let i=0;i<groups.length;i++){
   const token=groups[i],sc=new fabric.StaticCanvas(null,{width:w*PX_PER_MM,height:h*PX_PER_MM});
   try{const object=await tokenObject(token,sc);object.setCoords();const bounds=object.getBoundingRect(true,true);prepared.push({token,descriptor:serializeObject(object),width:Math.max(1,bounds.width),height:Math.max(1,bounds.height)})}finally{sc.dispose()}
   $('specialStatus').textContent='Preparazione '+(i+1)+' / '+groups.length
  }
  const commonScale=options.axis==='constant'?Math.min(...prepared.map(item=>Math.min(w*PX_PER_MM*.84/item.width,h*PX_PER_MM*.84/item.height))):null;
  for(let i=0;i<prepared.length;i++){
   const item=prepared[i],page=makePage(localizedPageName(i+1)+' · '+item.token,w,h),sc=new fabric.StaticCanvas(null,{width:w*PX_PER_MM,height:h*PX_PER_MM});
   try{const object=await instantiateObject(item.descriptor,sc);if(commonScale){object.set({left:sc.width/2,top:sc.height/2,scaleX:(object.scaleX||1)*commonScale,scaleY:(object.scaleY||1)*commonScale,dirty:true});object.setCoords()}else fitObjectList([object],sc.width,sc.height);page.objects=[serializeObject(object)];page.meta={special:'letters',group:item.token,explicit,fit:options.axis};pages.push(page)}finally{sc.dispose()}
  }
 }catch(e){error=e}finally{state.symbolRules=original.rules;state.smartEmoji=original.smart;$('fitAxis').value=original.axis;actionDepth--;button.disabled=false;syncHistoryButtons()}
 if(error){$('specialStatus').textContent='Generazione non riuscita: '+error.message;return}if(!pages.length)return;commitHistory();
 if(destination==='new'){const payload=currentDocument(false);payload.pages={whole:[],single:[],custom:pages};payload.state.pageIndex={whole:0,single:0,custom:0};payload.state.workspaceCustom=true;payload.assets=referencedAssets([{pages:payload.pages}]);await addProject(payload,localizedSpecialProjectName(explicit,text))}
 else{const first=replace?0:state.pages.custom.length;state.pages.custom=replace?pages:[...state.pages.custom,...pages];state.pageIndex.custom=first;scaleBaseline=null;await loadPage(state.pages.custom[first]);commitHistory();storeActiveDocument();scheduleAutosave()}
 $('specialStatus').textContent=pages.length+' pagine create.';toast(pages.length+' pagine create')
}
