 window.addEventListener('keydown',e=>{if(!(e.ctrlKey||e.metaKey)||e.altKey||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)||document.querySelector('dialog[open]')||!$('helpLayer').classList.contains('hidden'))return;const key=e.key.toLowerCase();if(key==='c'||key==='v'){e.preventDefault();e.stopImmediatePropagation();if(key==='c')copySelectionMultipurpose();else pasteSmartClipboard()}},true);
