function groupSelection(){if(cropSession||loadingPage)return;const active=canvas.getActiveObject();if(active?.type!=='activeSelection'||active.getObjects().length<2){toast('Seleziona almeno due oggetti');return}const selected=new Set(active.getObjects()),ordered=canvas.getObjects().filter(object=>selected.has(object));canvas.discardActiveObject();const normalized=new fabric.ActiveSelection(ordered,{canvas});canvas.setActiveObject(normalized);const touch=typeof canvasTouchUiActive==='function'&&canvasTouchUiActive(),group=normalized.toGroup(),appearance={borderColor:'#7549b8',cornerColor:'#7549b8',borderScaleFactor:touch?3:2.4};if(touch)Object.assign(appearance,touchControlProfile(true),{transparentCorners:false,cornerStyle:'circle'});group.objectType='group';group.projectId=uid('obj');group.set(appearance);group.setControlVisible('mtr',state.rotateEnabled);canvas.setActiveObject(group);canvas.requestRenderAll();saveActivePage();selectionChanged();toast('Oggetti raggruppati')}
