async function richToken(token,target,source=null){const chars=graphemes(token),hasEmoji=state.smartEmoji&&chars.some(isEmoji);if(!hasEmoji){const o=source?new fabric.Text(token,{fontFamily:source.fontFamily,fontSize:source.fontSize,fontWeight:source.fontWeight,fill:source.fill,stroke:source.stroke,strokeWidth:source.strokeWidth,paintFirst:'stroke',objectCaching:false,charSpacing:source.charSpacing,lineHeight:source.lineHeight,textAlign:source.textAlign,originX:'center',originY:'center'}):makeTextObj(token,0,0,100);o.objectType='text';o.outlineMode=source?.outlineMode??state.outline;o.projectId=uid('obj');target.add(o);return o}const runs=[];let text='';for(const c of chars){if(isEmoji(c)){if(text){runs.push({text});text=''}runs.push({emoji:c})}else text+=c}if(text)runs.push({text});const pieces=[];let x=0;for(const run of runs){let o;if(run.emoji)o=await instantiateObject(await makeGlyphDescriptor(run.emoji,0,0,source?.fontSize||100),target);else{o=source?new fabric.Text(run.text,{fontFamily:source.fontFamily,fontSize:source.fontSize,fontWeight:source.fontWeight,fill:source.fill,stroke:source.stroke,strokeWidth:source.strokeWidth,paintFirst:'stroke',objectCaching:false,charSpacing:source.charSpacing,lineHeight:source.lineHeight,textAlign:source.textAlign,originX:'center',originY:'center'}):makeTextObj(run.text,0,0,100);o.objectType='text';o.outlineMode=source?.outlineMode??state.outline;o.projectId=uid('obj');target.add(o)}o.set({left:x+o.getScaledWidth()/2,top:0});o.setCoords();x+=o.getScaledWidth()+4;pieces.push(o)}if(pieces.length===1)return pieces[0];pieces.forEach(o=>target.remove(o));const group=new fabric.Group(pieces,{originX:'center',originY:'center'});group.objectType='group';group.projectId=uid('obj');group.setControlVisible('mtr',state.rotateEnabled);target.add(group);return group}
tokenObject=richToken;
async function splitSelectedText(){if(cropSession||loadingPage)return;const source=canvas.getActiveObject();if(source?.objectType!=='text'){toast('Seleziona un singolo oggetto di testo');return}syncStateFromUI();const groups=groupGraphemes(graphemes(source.text)).map(x=>x.join(''));if(groups.length<2){toast('Il testo produce un solo gruppo');return}canvas.discardActiveObject();const pieces=[];let x=0;for(const token of groups){const o=await richToken(token,canvas,source);o.set({left:x+o.getScaledWidth()/2,top:0});o.setCoords();x+=o.getScaledWidth()+6;pieces.push(o)}pieces.forEach(o=>canvas.remove(o));const holder=new fabric.Group(pieces,{left:source.left,top:source.top,originX:source.originX||'center',originY:source.originY||'center',angle:source.angle||0,scaleX:source.scaleX||1,scaleY:source.scaleY||1});holder.objectType='group';holder.projectId=uid('obj');canvas.remove(source);canvas.add(holder);const selection=holder.toActiveSelection();canvas.setActiveObject(selection);canvas.requestRenderAll();saveActivePage();selectionChanged();toast('Testo diviso in '+groups.length+' oggetti')}
splitSelectedText=withHistory(splitSelectedText);

function insertPageAfterCurrent(){if(workspaceBusy())return;saveActivePage();const current=state.pages.custom[state.pageIndex.custom],page=makePage(localizedPageName(state.pages.custom.length+1),current.widthMm,current.heightMm);state.pages.custom.splice(state.pageIndex.custom+1,0,page);state.pageIndex.custom++;loadPage(page);commitHistory();scheduleAutosave()}
function movePage(from,to,open=true){const pages=state.pages.custom;if(from<0||from>=pages.length||to<0||to>=pages.length||from===to)return false;saveActivePage();const [page]=pages.splice(from,1);pages.splice(to,0,page);const currentId=currentPage?.id;state.pageIndex.custom=Math.max(0,pages.findIndex(p=>p.id===currentId));commitHistory();renderCustomChips();updatePageNavigation();if(open&&pages[to]){state.pageIndex.custom=to;loadPage(pages[to])}scheduleAutosave();return true}
function decoratePageChips(){const chips=[...$('customPageChips').querySelectorAll('.page-chip')];chips.forEach((chip,i)=>{chip.draggable=true;chip.dataset.index=i;chip.addEventListener('dragstart',e=>{pageDragIndex=i;chip.classList.add('dragging');e.dataTransfer.effectAllowed='move'});chip.addEventListener('dragend',()=>{pageDragIndex=-1;chip.classList.remove('dragging');chips.forEach(c=>c.classList.remove('drop-before','drop-after'))});chip.addEventListener('dragover',e=>{e.preventDefault();chips.forEach(c=>c.classList.remove('drop-before','drop-after'));chip.classList.add(e.offsetX<chip.offsetWidth/2?'drop-before':'drop-after')});chip.addEventListener('drop',e=>{e.preventDefault();const after=e.offsetX>=chip.offsetWidth/2,target=i+(after?1:0)-(pageDragIndex<i?1:0);movePage(pageDragIndex,clamp(target,0,state.pages.custom.length-1),false)})})}
