function setupCollapsible(){const sidebar=$('sidebar'),cards=[...sidebar.querySelectorAll(':scope > .card')].filter(c=>c.querySelector(':scope > .card-h'));cards.forEach((card,i)=>{card.dataset.section=card.id||'section-'+i;const head=card.querySelector(':scope > .card-h');head.setAttribute('role','button');head.tabIndex=0;head.setAttribute('aria-expanded',String(!card.classList.contains('collapsed')));const activate=()=>{if(preferences.accordion){cards.forEach(c=>c.classList.toggle('collapsed',c!==card));card.classList.remove('collapsed')}else card.classList.toggle('collapsed');cards.forEach(c=>c.querySelector(':scope > .card-h')?.setAttribute('aria-expanded',String(!c.classList.contains('collapsed'))));preferences.collapsed=cards.filter(c=>c.classList.contains('collapsed')).map(c=>c.dataset.section);writePreferences()};head.onclick=e=>{if(e.target.closest('button,input,select,a'))return;activate()};head.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();activate()}}});const applyStored=()=>cards.forEach(c=>c.classList.toggle('collapsed',preferences.collapsed?.includes(c.dataset.section)));applyStored();$('singleSection').checked=!!preferences.accordion;$('collapseSections').onclick=()=>{preferences.accordion=false;preferences.collapsed=cards.map(c=>c.dataset.section);$('singleSection').checked=false;applyStored();writePreferences()};$('expandSections').onclick=()=>{preferences.accordion=false;preferences.collapsed=[];$('singleSection').checked=false;applyStored();writePreferences()};$('singleSection').onchange=()=>{preferences.accordion=$('singleSection').checked;if(preferences.accordion){const visible=cards.find(c=>!c.classList.contains('collapsed'))||cards[0];cards.forEach(c=>c.classList.toggle('collapsed',c!==visible));preferences.collapsed=cards.filter(c=>c.classList.contains('collapsed')).map(c=>c.dataset.section)}writePreferences()};for(const button of sidebar.querySelectorAll('.quick-jump button')){const old=button.onclick;button.onclick=()=>{const labels={Pagina:'customCardTitle',Speciali:'specialCard',Testo:'textInput',Font:'fontMode',Emoji:'emojiSearch',Immagini:'uploadImageBtn',AI:'aiCard',Export:'pdfMode'},target=$(labels[button.textContent]),card=target?.closest('.card');if(card){if(preferences.accordion)cards.forEach(c=>c.classList.toggle('collapsed',c!==card));card.classList.remove('collapsed');card.querySelector(':scope > .card-h')?.setAttribute('aria-expanded','true');preferences.collapsed=cards.filter(c=>c.classList.contains('collapsed')).map(c=>c.dataset.section);writePreferences();card.dataset.flash='true';setTimeout(()=>delete card.dataset.flash,700);card.scrollIntoView({behavior:'smooth',block:'start'})}else old?.()}}}
