function beginRename(kind,id){hideNamingMenus();const item=kind==='project'?projects.find(p=>p.id===id):state.pages.custom.find(p=>p.id===id);if(!item)return;renameTarget={kind,id};$('renameDialogTitle').textContent=kind==='project'?'Rinomina progetto':'Rinomina pagina';$('renameInput').value=item.name;$('renameDialog').showModal();setTimeout(()=>{$('renameInput').focus();$('renameInput').select()},0)}
