async function aiAnnotatedReference(reference){if(!reference||!aiHasUsableAnnotations())return null;const image=new Image();image.src=reference.dataUrl;await image.decode();const surface=document.createElement('canvas');surface.width=reference.width||image.naturalWidth;surface.height=reference.height||image.naturalHeight;const context=surface.getContext('2d',{alpha:true});context.drawImage(image,0,0,surface.width,surface.height);for(const marker of state.aiReferenceAnnotations.markers)drawAiAnnotationMarker(context,marker,surface.width,surface.height,false,1);const result={dataUrl:surface.toDataURL('image/png'),mime:'image/png',width:surface.width,height:surface.height};surface.width=surface.height=1;image.src='';return result}
