async function openAiAnnotationEditor(){if(!state.aiReference||!aiAnnotationModelCompatible())return;aiAnnotationOpener=document.activeElement;aiAnnotationDraft=cloneData(state.aiReferenceAnnotations||emptyAiAnnotations());aiAnnotationSelected=null;setAiAnnotationTool('select');openAiAnnotationComments(false);const dialog=$('aiAnnotationDialog'),image=new Image();image.src=state.aiReference.dataUrl;await image.decode();aiAnnotationImage=image;const canvas=aiAnnotationCanvas(),sourceWidth=state.aiReference.width||image.naturalWidth,sourceHeight=state.aiReference.height||image.naturalHeight,previewScale=Math.min(1,2048/Math.max(sourceWidth,sourceHeight));canvas.width=Math.max(1,Math.round(sourceWidth*previewScale));canvas.height=Math.max(1,Math.round(sourceHeight*previewScale));const context=canvas.getContext('2d');context.clearRect(0,0,canvas.width,canvas.height);context.drawImage(image,0,0,canvas.width,canvas.height);aiAnnotationPreviewHasTransparency=aiAnnotationCanvasHasTransparency(canvas);const tooltip=$('desktopTooltip');if(tooltip&&!dialog.contains(tooltip)){aiAnnotationTooltipHome={parent:tooltip.parentNode,next:tooltip.nextSibling};dialog.append(tooltip)}dialog.showModal();syncAiAnnotationEditorUi();syncAiAnnotationPreviewBackground();requestAnimationFrame(fitAiAnnotation)}
