function normalizedPromptTitle(value){return String(value||'').trim().toLocaleLowerCase(appLocale())}
function normalizePromptLibraryPayload(payload){const sources=Array.isArray(payload)?payload:payload?.type==='chicCanva-prompt-library'||Array.isArray(payload?.prompts)?payload.prompts:null;if(!Array.isArray(sources))throw new Error('Libreria non riconosciuta');if(sources.length>2000)throw new Error('La libreria contiene troppi prompt');const entries=[],now=new Date().toISOString();for(const source of sources){if(!source||typeof source!=='object'||!String(source.title||'').trim()||!String(source.prompt||'').trim())throw new Error('Un prompt non contiene titolo o testo');const prompt=String(source.prompt);if(prompt.length>100000)throw new Error('Un prompt supera il limite consentito');let reference=null;if(source.reference?.dataUrl){const dataUrl=String(source.reference.dataUrl);if(!/^data:image\//i.test(dataUrl)||dataUrl.length>24*1024*1024)throw new Error('Un’immagine associata non è valida o è troppo grande');reference=cloneData(source.reference)}entries.push({id:String(source.id||uid('prompt')).slice(0,160),title:String(source.title).trim().slice(0,120),tags:promptTags(source.tags),description:String(source.description||'').slice(0,600),prompt,style:String(source.style||'prompt').slice(0,160),reference,createdAt:source.createdAt||now,updatedAt:now})}return{type:'chicCanva-prompt-library',version:1,prompts:entries}}
