const clipartPageCache=new Map();
function clipartUrls(id,slug='clipart'){return{thumbnail:'https://openclipart.org/image/400px/'+id,large:'https://openclipart.org/image/800px/'+id,download:'https://openclipart.org/download/'+id,detail:'https://openclipart.org/detail/'+id+'/'+slug}}
function normalizeClipartTitle(value,slug){const text=String(value||'').replace(/\s+/g,' ').trim();return text||String(slug||'clipart').replace(/-/g,' ')}
function parseOpenclipartResults(html,limit=CLIPART_RESULTS_PER_PAGE){const doc=new DOMParser().parseFromString(html,'text/html'),seen=new Set(),items=[],maximum=Math.max(1,Number(limit)||CLIPART_RESULTS_PER_PAGE);for(const link of doc.querySelectorAll('a[href*="/detail/"]')){const href=link.getAttribute('href')||'',match=href.match(/\/detail\/(\d+)(?:\/([^?#"']+))?/);if(!match||seen.has(match[1]))continue;seen.add(match[1]);const id=match[1],slug=(match[2]||'clipart').replace(/\/$/,'');let title=normalizeClipartTitle(link.getAttribute('title')||link.querySelector('img')?.alt||link.textContent,slug);if(/^download$/i.test(title))title=normalizeClipartTitle('',slug);items.push({id,slug,title,...clipartUrls(id,slug)});if(items.length>=maximum)break}return items}
