function renderClipartResults(){const grid=$('clipartResults');grid.replaceChildren();for(const item of clipartItems){const card=document.createElement('article');card.className='clipart-item';card.dataset.id=item.id;const preview=document.createElement('button');preview.className='clipart-thumb';preview.type='button';preview.title='Apri anteprima di '+item.title;const image=document.createElement('img');preview.classList.add('loading');image.alt=item.title;image.loading='lazy';image.onload=()=>preview.classList.remove('loading');image.onerror=()=>{preview.classList.remove('loading');preview.classList.add('load-error')};image.src=item.thumbnail;if(image.complete)queueMicrotask(()=>image.naturalWidth?image.onload():image.onerror());preview.append(image);const title=document.createElement('strong');title.textContent=item.title;title.title=item.title;const actions=document.createElement('div');actions.className='clipart-item-actions';const open=document.createElement('button');open.className='btn';open.type='button';open.textContent='Anteprima';open.dataset.clipartAction='preview';open.dataset.id=item.id;actions.append(open);if($('clipartUsePuter').checked){const insert=document.createElement('button');insert.className='btn accent';insert.type='button';insert.textContent='Inserisci';insert.dataset.clipartAction='insert';insert.dataset.id=item.id;actions.append(insert)}preview.dataset.clipartAction='preview';preview.dataset.id=item.id;card.append(preview,title,actions);grid.append(card)}$('clipartPages').classList.toggle('hidden',!clipartItems.length);$('clipartPageLabel').textContent='Pagina '+clipartPage;$('clipartPrev').disabled=clipartPage<=1;$('clipartNext').disabled=!clipartHasNext}
async function searchClipart(page=1,{navigation=false}={}){
 const serial=++clipartSearchSerial,button=$('clipartSearchBtn');let keyword=$('clipartQuery').value.trim(),category=$('clipartCategory').value;
 if(!keyword&&!category){$('clipartStatus').textContent='Scrivi una parola o scegli una categoria.';return}
 button.disabled=true;button.setAttribute('aria-busy','true');button.innerHTML='<span class="spinner"></span> Ricerca…';$('clipartResults').setAttribute('aria-busy','true');$('clipartResults').innerHTML='<div class="clipart-loading"><span class="spinner"></span> Traduco e cerco le clipart…</div>';$('clipartPages').classList.add('hidden');$('clipartStatus').textContent='Preparazione della ricerca…';
 try{let query;if(navigation&&clipartLastQuery)query=clipartLastQuery;else{keyword=await translateClipartKeyword(keyword);if(serial!==clipartSearchSerial)return;query=[keyword,category].filter(Boolean).join(' ').trim();clipartLastQuery=query;clipartPageCache.clear()}clipartPage=Math.max(1,page);$('clipartStatus').textContent=(clipartTranslationNote?clipartTranslationNote+' · ':'')+'Ricerca di “'+query+'”…';const resultPage=await clipartItemsForPage(query,clipartPage);if(serial!==clipartSearchSerial)return;clipartItems=resultPage.items;clipartHasNext=resultPage.hasNext;renderClipartResults();const via=clipartSearchTransport==='webserver locale'?' · tramite webserver locale':'';const result=clipartItems.length?clipartItems.length+' risultati mostrati · '+query+via:'Nessun risultato in questa pagina.';$('clipartStatus').textContent=(clipartTranslationNote?clipartTranslationNote+' · ':'')+result}
 catch(error){if(serial!==clipartSearchSerial)return;clipartItems=[];clipartHasNext=false;renderClipartResults();$('clipartStatus').textContent='Ricerca non riuscita: '+(error.message||error)+'. Se un’estensione blocca Openclipart, usa il launcher aggiornato.'}
 finally{if(serial===clipartSearchSerial){button.disabled=false;button.removeAttribute('aria-busy');button.textContent='Cerca';$('clipartResults').removeAttribute('aria-busy')}}
}
function clipartById(id){return clipartItems.find(item=>item.id===String(id))}
function openClipartPreview(item){if(!item)return;clipartCurrent=item;$('clipartPreviewTitle').textContent=item.title;$('clipartPreviewMeta').textContent='Openclipart #'+item.id;$('clipartPreviewImage').src=item.large;$('clipartPreviewImage').alt=item.title;$('clipartPreviewStatus').textContent='';const unavailable=location.protocol==='file:';$('clipartInsertPuterBtn').disabled=unavailable;$('clipartInsertPuterBtn').title=unavailable?'Per usare la funzione apri l’app tramite webserver':'';$('clipartPreviewDialog').showModal()}
