async function insertClipart(item){if(!item)return;if(location.protocol==='file:'){toast('Per usare la funzione apri l’app tramite webserver');return}const status=$('clipartPreviewDialog').open?$('clipartPreviewStatus'):$('clipartStatus');status.textContent='Download tramite Puter…';try{const file=await fetchClipartFile(item);const named=new File([file],cleanExportName(item.title,'clipart')+'.'+((file.type||'image/png').split('/')[1]||'png'),{type:file.type||'image/png'});await handleImageUpload(named);status.textContent='Clipart inserita nel canvas.';$('clipartPreviewDialog').close();toast('Clipart inserita');schedulePuterUsageRefresh()}catch(error){status.textContent='Inserimento non riuscito: '+(error.message||error)}}
function formatPuterMoney(credits){if(!Number.isFinite(Number(credits)))return'—';const dollars=Number(credits)/2000;return new Intl.NumberFormat(appLocale(),{style:'currency',currency:'USD',minimumFractionDigits:dollars<0.01?4:2,maximumFractionDigits:dollars<0.01?4:2}).format(dollars)}
