async function refreshPuterUsage(silent=false){const box=$('puterUsage');if(!box||location.protocol==='file:'){box?.classList.add('hidden');return}try{await ensurePuter();if(!window.puter?.auth?.isSignedIn||!await Promise.resolve(puter.auth.isSignedIn())){box.classList.add('hidden');return}if(!puter.auth.getMonthlyUsage)throw new Error('Consumo non disponibile in questa versione di Puter');const usage=await puter.auth.getMonthlyUsage(),info=usage?.allowanceInfo||{},total=Number(info.monthUsageAllowance),remaining=Number(info.remaining),used=Math.max(0,total-remaining),percent=total>0?clamp(used/total*100,0,100):0,callCount=Object.values(usage?.appTotals||{}).reduce((sum,item)=>sum+Number(item?.count||0),0);box.classList.remove('hidden');$('puterUsageBar').style.width=percent+'%';const progress=box.querySelector('[role="progressbar"]');progress.setAttribute('aria-valuenow',String(Math.round(percent)));$('puterUsageUsed').textContent='Usato '+Math.round(percent)+'% · '+formatPuterCredits(used)+' · '+formatPuterMoney(used);$('puterUsageRemaining').textContent='Rimasto '+Math.round(100-percent)+'% · '+formatPuterCredits(remaining)+' · '+formatPuterMoney(remaining);$('puterUsageDetail').textContent='Plafond '+formatPuterCredits(total)+' · '+formatPuterMoney(total)+(callCount?' · '+callCount+' chiamate dell’app':'')+'. Il valore è letto dinamicamente dall’account; il controvalore in dollari è indicativo.'}catch(error){if(!silent){box.classList.remove('hidden');$('puterUsageDetail').textContent='Aggiornamento non riuscito: '+(error.message||error)}}}
