 if(host==='localhost'||host.endsWith('.localhost')||host.endsWith('.local')||host.endsWith('.lan')||host.endsWith('.internal')||host.endsWith('.home.arpa'))return false;
 if(host==='::1'||host.includes(':')||/^\d{1,3}(?:\.\d{1,3}){3}$/.test(host))return false;
