function bindUiLongPress(){document.addEventListener('pointerdown',event=>{if(event.pointerType!=='touch')return;const target=event.target.closest('#rotateTool,#selectTool,#copyTool,#bringFrontTool,#sendBackTool,#undoBtn,#redoBtn,.project-name,.page-chip,.preview-page');if(!target)return;clearTimeout(uiLongPressTimer);uiLongPressConsumed=false;uiLongPressStart={target,x:event.clientX,y:event.clientY};uiLongPressTimer=setTimeout(()=>{const saved=uiLongPressStart;uiLongPressStart=null;if(!saved)return;uiLongPressConsumed=true;saved.target.dispatchEvent(new MouseEvent('contextmenu',{bubbles:true,cancelable:true,clientX:saved.x,clientY:saved.y}));navigator.vibrate?.(25)},1200)},{passive:true});document.addEventListener('pointermove',event=>{if(uiLongPressStart&&Math.hypot(event.clientX-uiLongPressStart.x,event.clientY-uiLongPressStart.y)>12){clearTimeout(uiLongPressTimer);uiLongPressStart=null}},{passive:true});for(const name of ['pointerup','pointercancel'])document.addEventListener(name,()=>{clearTimeout(uiLongPressTimer);uiLongPressStart=null},{passive:true});document.addEventListener('click',event=>{if(!uiLongPressConsumed)return;uiLongPressConsumed=false;event.preventDefault();event.stopImmediatePropagation()},true)}

function historyObjectCount(entry){let count=0;for(const pages of Object.values(entry?.pages||{}))for(const page of pages)count+=(page.objects||[]).length;return count}
function inferHistoryLabel(previous,current){if(!previous)return'Inizio progetto';const beforePages=(previous.pages?.custom||[]).length,afterPages=(current.pages?.custom||[]).length;if(afterPages>beforePages)return'Pagina aggiunta';if(afterPages<beforePages)return'Pagina eliminata';const before=historyObjectCount(previous),after=historyObjectCount(current);if(after>before)return'Oggetto aggiunto';if(after<before)return'Oggetto eliminato';if(JSON.stringify(current.pages||{}).includes('"objectType":"colorized"'))return'Colorizzazione o modifica immagine';return'Modifica oggetti o pagina'}
const interactionCommitHistory=commitHistory;commitHistory=function(){const beforeLength=historyEntries.length,beforeCursor=historyCursor,previous=historyEntries[historyCursor];interactionCommitHistory();if(historyEntries.length!==beforeLength||historyCursor!==beforeCursor){const entry=historyEntries[historyCursor];if(entry&&!entry.historyInfo)entry.historyInfo={label:inferHistoryLabel(previous,entry),at:new Date().toISOString()}}};
